-- Tập luyện song ngữ: dịch nội dung sang tiếng Anh cho HLV nước ngoài (anh Long chốt 27/11/2026).
-- · Thêm cột *_en còn thiếu (bài tập, câu luật, lộ trình, chi phí, nhu cầu, giới hạn theo tuổi).
-- · Điền bản tiếng Anh theo câu tiếng Việt (chỉ điền ô còn trống, không ghi đè bản admin đã sửa).
--   Giáo án Break 90/80/70: dùng nguyên văn tài liệu gốc tiếng Anh VN Centre có bản quyền khi đối chiếu được; phần còn lại Minh dịch.
-- · Hàm trả thêm bản tiếng Anh: training_class_pending, training_quiz_questions, training_submit_quiz.
-- Câu tiếng Việt nào admin đã sửa khác bản gốc thì không khớp, giữ trống _en (app hiện tiếng Việt).

alter table public.training_drills
  add column if not exists unit_en text,
  add column if not exists goal_en text,
  add column if not exists steps_en jsonb not null default '[]' check (jsonb_typeof(steps_en) = 'array'),
  add column if not exists easier_en text,
  add column if not exists harder_en text,
  add column if not exists safety_en text;
alter table public.training_quiz_questions
  add column if not exists options_en jsonb not null default '[]' check (jsonb_typeof(options_en) = 'array'),
  add column if not exists explain_en text;
alter table public.training_cost_items add column if not exists note_en text;
alter table public.training_path_steps
  add column if not exists benefit_en text,
  add column if not exists hcp_note_en text,
  add column if not exists opportunity_en text,
  add column if not exists focus_en text;
alter table public.training_finance_plans
  add column if not exists summary_en text,
  add column if not exists tradeoff_en text;
alter table public.training_needs add column if not exists advice_en text;
alter table public.training_age_limits
  add column if not exists sleep_en text,
  add column if not exists note_en text;

-- Bảng dịch tạm (câu tiếng Việt → tiếng Anh)
