"Đặt 6 bóng quanh lỗ hoặc cốc, cách 1 m như mặt đồng hồ.": "Place 6 balls around a hole or cup, 1 m away, like the face of a clock.",
"Đặt chai nước ở 5, 12, 20 và 28 ft.": "Place water bottles at 5, 12, 20 and 28 ft.",
"Đặt cuốn sách nhẹ hoặc quả bóng ngay sau đầu gậy ở tư thế setup.": "Place a light book or a ball just behind the clubhead at setup.",
"Đặt cốc nằm nghiêng làm lỗ, cách 5 ft (1,5 m).": "Lay a cup on its side as the hole, 5 ft (1.5 m) away.",
"Đặt gậy ngang sau vai.": "Hold a club across the back of your shoulders.",
"Đặt gậy sắt dưới đất làm đường thẳng, 5 phút putt dọc theo gậy (không cần lỗ)": "Lay an iron on the ground as a straight line and putt along it for 5 minutes (no hole needed)",
"Đặt hai bóng chồng lên nhau theo chiều dọc mặt gậy, mỗi bóng chiếm nửa mặt gậy.": "Stack two balls vertically against the putter face, each covering half of it.",
"Đặt hai cuốn sách song song, khe vừa lọt đầu gậy putter.": "Place two books parallel, with a gap just wide enough for the putter head.",
"Đặt khăn cách 10 ft (3 m). Chip để bóng rơi trúng khăn; bóng lăn ra ngoài không sao.": "Place a towel 10 ft (3 m) away. Chip so the ball lands on the towel; it's fine if it rolls off.",
"Đặt mốc 2, 4 và 6 m.": "Mark stations at 2, 4 and 6 m.",
"Đặt một chiếc khăn làm điểm rơi, cách 3 bước.": "Place a towel 3 paces away as your landing spot.",
"Đặt một lá bài cách 10 ft.": "Place a playing card 10 ft away.",
"Đặt mục tiêu ở 4, 8, 12, 16 ft, lần lượt 1, 3, 5, 10 điểm.": "Place targets at 4, 8, 12 and 16 ft, worth 1, 3, 5 and 10 points.",
"Đặt que căn hướng. 10 bóng tới 100 y, 10 bóng tới 125 y, 10 bóng tới 150 y.": "Lay down an alignment stick. 10 balls to 100 y, 10 to 125 y and 10 to 150 y.",
"Đặt sát mặt đất": "Placed on the ground",
"Đặt thước dài vuông góc với putter.": "Lay a long ruler at right angles to the putter.",
"Đặt xô hoặc rổ cách 5 m.": "Place a bucket or basket 5 m away.",
"Đặt điện thoại ở hai góc: chính diện và dọc đường bóng.": "Set up your phone from two angles: face-on and down the line.",
"Đồng hồ 1 mét": "1-metre clock",
"Đổi biên độ, quan sát bóng đi xa bao nhiêu. Mỗi hiệp 20 lượt.": "Change the length and watch how far the ball goes. 20 strokes per set.",
"Đủ 30 bóng liên tiếp là xong bài.": "The drill is done when you've made 30 in a row.",
"Đứng một chân": "Single-leg balance",
"Đứng một chân, hai tay khoanh trước ngực.": "Stand on one leg with your arms folded across your chest.",
"Đứng quay mặt vào tường, đầu gậy sắt cách tường một khoảng nhỏ.": "Stand facing a wall with the head of an iron a little way from it.",
"Đứng sau bóng chọn mục tiêu, 1 lần swing tập, rồi đánh": "Stand behind the ball, pick your target, take 1 practice swing, then hit",
"Đứng trước gương, không cần bóng.": "Stand in front of a mirror, no ball needed.",
"điểm": "points",
"động tác": "exercises",
"Ưu tiên lỗ trung bình hoặc lỗ xa; nếu không có thì dùng lỗ gần": "Find a middle hole if possible or far hole but if none then use short hole"
}$map$::jsonb);
create unique index on _tr (vi);

create or replace function pg_temp.tr(p text) returns text language sql stable as $f$ select en from _tr where vi = p $f$;
-- Dịch mảng chuỗi; còn câu chưa có bản dịch thì trả null (giữ nguyên tiếng Việt)
create or replace function pg_temp.tr_arr(p jsonb) returns jsonb language sql stable as $f$
  select case when count(*) = count(t.en) then coalesce(jsonb_agg(to_jsonb(t.en) order by x.o), '[]') end
  from jsonb_array_elements_text(p) with ordinality x(s, o) left join _tr t on t.vi = x.s
$f$;

-- Giáo án (Có Handicap, Break 100, Break 90/80/70)
update public.training_program_blocks set title_en = pg_temp.tr(title_vi)
where coalesce(title_en, '') = '' and pg_temp.tr(title_vi) is not null;
update public.training_program_blocks b
set lines = (select coalesce(jsonb_agg(case when coalesce(l ->> 'en', '') = '' and t.en is not null then l || jsonb_build_object('en', t.en) else l end
                                       order by x.o), '[]')
             from jsonb_array_elements(b.lines) with ordinality x(l, o) left join _tr t on t.vi = x.l ->> 'vi')
where exists (select 1 from jsonb_array_elements(b.lines) l join _tr t on t.vi = l ->> 'vi' where coalesce(l ->> 'en', '') = '');

-- Thư viện bài tập
update public.training_drills set
  title_en = case when coalesce(title_en, '') = '' then coalesce(pg_temp.tr(title_vi), title_en) else title_en end,
  unit_en = coalesce(unit_en, pg_temp.tr(unit_vi)),
  goal_en = coalesce(goal_en, pg_temp.tr(goal_vi)),
  easier_en = coalesce(easier_en, pg_temp.tr(easier_vi)),
  harder_en = coalesce(harder_en, pg_temp.tr(harder_vi)),
  safety_en = coalesce(safety_en, pg_temp.tr(safety_vi)),
  steps_en = case when jsonb_array_length(steps_en) = 0 then coalesce(pg_temp.tr_arr(steps), '[]') else steps_en end;

-- Thẻ thử thách (tên, cách làm, tên từng phần)
update public.training_challenges c set
  title_en = case when coalesce(title_en, '') = '' then coalesce(pg_temp.tr(title_vi), title_en) else title_en end,
  how_en = coalesce(nullif(how_en, ''), pg_temp.tr(how_vi)),
  parts = (select jsonb_agg(case when coalesce(p ->> 'label_en', '') = '' and pg_temp.tr(p ->> 'label_vi') is not null
                                 then p || jsonb_build_object('label_en', pg_temp.tr(p ->> 'label_vi')) else p end order by x.o)
           from jsonb_array_elements(c.parts) with ordinality x(p, o));

-- Câu hỏi luật
update public.training_quiz_questions set
  question_en = case when coalesce(question_en, '') = '' then coalesce(pg_temp.tr(question_vi), question_en) else question_en end,
  options_en = case when jsonb_array_length(options_en) = 0 then coalesce(pg_temp.tr_arr(options), '[]') else options_en end,
  explain_en = coalesce(explain_en, pg_temp.tr(explain_vi));

-- Lộ trình, chi phí, phương án, nhu cầu, giới hạn theo tuổi
update public.training_path_steps set
  title_en = case when coalesce(title_en, '') = '' then coalesce(pg_temp.tr(title_vi), title_en) else title_en end,
  benefit_en = coalesce(benefit_en, pg_temp.tr(benefit_vi)),
  hcp_note_en = coalesce(hcp_note_en, pg_temp.tr(hcp_note_vi)),
  opportunity_en = coalesce(opportunity_en, pg_temp.tr(opportunity_vi)),
  focus_en = coalesce(focus_en, pg_temp.tr(focus_vi));
update public.training_cost_items set
  name_en = case when coalesce(name_en, '') = '' then coalesce(pg_temp.tr(name_vi), name_en) else name_en end,
  gain_en = coalesce(nullif(gain_en, ''), pg_temp.tr(gain_vi)),
  note_en = coalesce(note_en, pg_temp.tr(note_vi));
update public.training_finance_plans set
  summary_en = coalesce(summary_en, pg_temp.tr(summary_vi)),
  tradeoff_en = coalesce(tradeoff_en, pg_temp.tr(tradeoff_vi));
update public.training_needs set
  title_en = case when coalesce(title_en, '') = '' then coalesce(pg_temp.tr(title_vi), title_en) else title_en end,
  advice_en = coalesce(advice_en, pg_temp.tr(advice_vi));
update public.training_age_limits set
  sleep_en = coalesce(sleep_en, pg_temp.tr(sleep_vi)),
  note_en = coalesce(note_en, pg_temp.tr(note_vi));

drop function pg_temp.tr_arr(jsonb);
drop function pg_temp.tr(text);
drop table _tr;

-------------------------------------------------------------------------------
-- Hàm trả thêm bản tiếng Anh
-------------------------------------------------------------------------------
create or replace function public.training_class_pending(p_class_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not (public.is_center_staff() or public.is_class_staff(p_class_id)) then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'id', r.id, 'student_id', s.id, 'full_name', s.full_name, 'challenge_code', c.code, 'title_vi', c.title_vi, 'title_en', c.title_en,
      'level', c.level_number, 'parts', c.parts, 'made', to_jsonb(r.made), 'video_url', r.video_url, 'submitted_as', r.submitted_as,
      'created_at', r.created_at)
      order by r.created_at)
    from public.training_challenge_results r
    join public.training_challenges c on c.id = r.challenge_id
    join public.students s on s.id = r.student_id
    where r.status = 'pending' and exists (select 1 from public.enrollments e where e.class_id = p_class_id and e.student_id = r.student_id and e.status = 'active')), '[]');
end $$;

create or replace function public.training_quiz_questions(p_program_code text)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'question_vi', question_vi, 'question_en', question_en, 'options', options,
                                               'options_en', options_en)
                            order by sort_order, created_at), '[]')
  from public.training_quiz_questions where program_code = p_program_code and is_active and auth.uid() is not null;
$$;

create or replace function public.training_submit_quiz(p_student_id uuid, p_program_code text, p_answers jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_total int; v_score int; v_ratio numeric; v_passed boolean; v_detail jsonb;
begin
  if not coalesce(public.can_manage_student(p_student_id) or public.training_is_self_student(p_student_id), false) or not public.training_enabled() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if jsonb_typeof(coalesce(p_answers, 'null')) <> 'object' then raise exception 'invalid_answers' using errcode = '22023'; end if;
  select count(*), count(*) filter (where (p_answers ->> q.id::text)::int = q.correct_index),
         coalesce(jsonb_agg(jsonb_build_object('id', q.id, 'correct_index', q.correct_index,
                                               'chosen', (p_answers ->> q.id::text)::int, 'explain_vi', q.explain_vi, 'explain_en', q.explain_en)
                            order by q.sort_order, q.created_at), '[]')
  into v_total, v_score, v_detail
  from public.training_quiz_questions q where q.program_code = p_program_code and q.is_active;
  if v_total = 0 then raise exception 'quiz_not_found' using errcode = '22023'; end if;
  v_ratio := public.setting_num('training.quiz_pass_ratio', 0.8);
  v_passed := v_score >= ceil(v_total * v_ratio);
  insert into public.training_quiz_attempts (student_id, program_code, answers, score, total, passed, submitted_by)
  values (p_student_id, p_program_code, p_answers, v_score, v_total, v_passed, auth.uid());
  return jsonb_build_object('score', v_score, 'total', v_total, 'passed', v_passed,
                            'need', ceil(v_total * v_ratio)::int, 'detail', v_detail);
end $$;
